create table if not exists public.deal_events (
  id uuid primary key default gen_random_uuid(), deal_id uuid not null references public.deals(id) on delete cascade,
  event_type text not null, from_value text, to_value text, reason text, metadata jsonb not null default '{}'::jsonb,
  performed_by uuid references public.profiles(id), created_at timestamptz not null default now()
);
alter table public.deal_events enable row level security;
create index if not exists idx_deal_events_deal_created on public.deal_events(deal_id,created_at desc);
create or replace function public.deal_current_role() returns text language sql stable security definer set search_path=public as $$ select coalesce((select role::text from public.profiles where id=auth.uid() and active=true limit 1),'unknown') $$;
create or replace function public.deal_can_write() returns boolean language sql stable security definer set search_path=public as $$ select public.deal_current_role() in ('admin','ceo','manager','dealer') $$;
create or replace function public.deal_can_approve() returns boolean language sql stable security definer set search_path=public as $$ select public.deal_current_role() in ('admin','ceo','manager') $$;
revoke all on function public.deal_current_role() from public,anon; revoke all on function public.deal_can_write() from public,anon; revoke all on function public.deal_can_approve() from public,anon;
grant execute on function public.deal_current_role() to authenticated,service_role; grant execute on function public.deal_can_write() to authenticated,service_role; grant execute on function public.deal_can_approve() to authenticated,service_role;
drop policy if exists "Admins and managers can update all deals" on public.deals; drop policy if exists "Admins and managers can view all deals" on public.deals; drop policy if exists "Admins can delete deals" on public.deals; drop policy if exists "Dealers can create their own deals" on public.deals; drop policy if exists "Dealers can update their own draft deals" on public.deals; drop policy if exists "Dealers can view their own deals" on public.deals; drop policy if exists deals_read_roles on public.deals; drop policy if exists deals_insert_roles on public.deals; drop policy if exists deals_update_roles on public.deals;
create policy deals_read_roles on public.deals for select to authenticated using (public.deal_current_role() in ('admin','ceo','manager','finance','operations','logistics') or (public.deal_current_role()='dealer' and dealer_id=auth.uid()));
create policy deals_insert_roles on public.deals for insert to authenticated with check (public.deal_can_write() and (public.deal_current_role()<>'dealer' or dealer_id=auth.uid()));
create policy deals_update_roles on public.deals for update to authenticated using (public.deal_current_role() in ('admin','ceo','manager') or (public.deal_current_role()='dealer' and dealer_id=auth.uid() and status in ('draft','review'))) with check (public.deal_current_role() in ('admin','ceo','manager') or (public.deal_current_role()='dealer' and dealer_id=auth.uid()));
drop policy if exists deal_events_read_authenticated on public.deal_events; create policy deal_events_read_authenticated on public.deal_events for select to authenticated using (true);
create or replace function public.deal_creation_guard() returns trigger language plpgsql set search_path=public as $$ begin if current_user not in ('postgres','service_role') then new.status:='draft'::public.deal_status; new.payment_status:='Pending'; new.shipment_status:='Planning'; if public.deal_current_role()='dealer' then new.dealer_id:=auth.uid(); end if; end if; if coalesce(new.profit,new.profit_aed,0)<0 then raise exception 'A deal cannot be created with negative gross profit.'; end if; return new; end $$;
drop trigger if exists trg_deal_creation_guard on public.deals; create trigger trg_deal_creation_guard before insert on public.deals for each row execute function public.deal_creation_guard();
create or replace function public.deal_sensitive_update_guard() returns trigger language plpgsql set search_path=public as $$ begin if current_user not in ('postgres','service_role') then if new.status is distinct from old.status or new.dealer_id is distinct from old.dealer_id or new.payment_status is distinct from old.payment_status or new.shipment_status is distinct from old.shipment_status then raise exception 'Deal lifecycle, owner, payment and shipment state must use controlled workflows.'; end if; if old.status in ('pending','approved','completed') and (new.customer_id is distinct from old.customer_id or new.supplier_id is distinct from old.supplier_id or new.amount is distinct from old.amount or new.buy_currency is distinct from old.buy_currency or new.sell_currency is distinct from old.sell_currency or new.buy_price is distinct from old.buy_price or new.sell_price is distinct from old.sell_price or new.profit is distinct from old.profit or new.profit_aed is distinct from old.profit_aed or new.quantity is distinct from old.quantity or new.commodity is distinct from old.commodity or new.incoterm is distinct from old.incoterm) then raise exception 'Submitted or approved commercial terms are locked. Reopen the deal before changing them.'; end if; end if; return new; end $$;
drop trigger if exists trg_deal_sensitive_update_guard on public.deals; create trigger trg_deal_sensitive_update_guard before update on public.deals for each row execute function public.deal_sensitive_update_guard();
create or replace function public.deal_readiness_v1(p_deal_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare d public.deals; blockers jsonb:='[]'::jsonb; warnings jsonb:='[]'::jsonb; c_status text; s_status text; s_kyc text; s_exp date; gp numeric; margin numeric; begin select * into d from public.deals where id=p_deal_id; if not found then raise exception 'Deal not found.'; end if; if d.customer_id is null then blockers:=blockers||jsonb_build_array('Customer is required.'); else select status into c_status from public.customers where id=d.customer_id; if c_status is distinct from 'active' then blockers:=blockers||jsonb_build_array('Customer account must be active.'); end if; end if; if d.supplier_id is not null then select status,kyc_status,kyc_expiry_date into s_status,s_kyc,s_exp from public.suppliers where id=d.supplier_id; if s_status is distinct from 'active' then blockers:=blockers||jsonb_build_array('Supplier must be active.'); end if; if s_kyc is distinct from 'approved' then blockers:=blockers||jsonb_build_array('Supplier KYC must be approved.'); end if; if s_exp is not null and s_exp<current_date then blockers:=blockers||jsonb_build_array('Supplier KYC is expired.'); end if; else warnings:=warnings||jsonb_build_array('No supplier is linked to this deal.'); end if; if coalesce(d.amount,0)<=0 then blockers:=blockers||jsonb_build_array('Deal value must be greater than zero.'); end if; if d.commodity is not null and coalesce(d.quantity,0)<=0 then blockers:=blockers||jsonb_build_array('Commercial quantity must be greater than zero.'); end if; gp:=coalesce(d.profit,d.profit_aed,0); if gp<0 then blockers:=blockers||jsonb_build_array('Gross profit cannot be negative.'); elsif gp=0 then warnings:=warnings||jsonb_build_array('Gross profit is zero.'); end if; margin:=case when coalesce(d.amount,0)>0 then round((gp/d.amount)*100,2) else 0 end; return jsonb_build_object('ready',jsonb_array_length(blockers)=0,'blockers',blockers,'warnings',warnings,'gross_profit',gp,'margin_percent',margin,'status',d.status::text); end $$;
create or replace function public.deal_submit_review_v1(p_deal_id uuid,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare d public.deals; r jsonb; a_id uuid; role text:=public.deal_current_role(); begin if role not in ('admin','ceo','manager','dealer') then raise exception 'Deal submission is not permitted for this role.'; end if; select * into d from public.deals where id=p_deal_id for update; if not found then raise exception 'Deal not found.'; end if; if role='dealer' and d.dealer_id<>auth.uid() then raise exception 'Dealer users may submit only their own deals.'; end if; if d.status not in ('draft','review') then raise exception 'Only draft or review deals can be submitted.'; end if; r:=public.deal_readiness_v1(p_deal_id); if not coalesce((r->>'ready')::boolean,false) then raise exception 'Deal is not ready for approval: %',r->'blockers'; end if; delete from public.approvals where entity_type='deal' and entity_id=p_deal_id and approval_type='commercial' and status='pending'; insert into public.approvals(entity_type,entity_id,approval_type,requested_by,status,comments) values('deal',p_deal_id,'commercial',auth.uid(),'pending',nullif(trim(coalesce(p_reason,'')),'')) returning id into a_id; update public.deals set status='pending',updated_at=now() where id=p_deal_id; insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,metadata,performed_by) values(p_deal_id,'submitted_for_approval',d.status::text,'pending',nullif(trim(coalesce(p_reason,'')),''),r,auth.uid()); return jsonb_build_object('deal_id',p_deal_id,'status','pending','approval_id',a_id,'readiness',r); end $$;
create or replace function public.deal_decide_v1(p_deal_id uuid,p_decision text,p_comments text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare d public.deals; a public.approvals; r jsonb; begin if not public.deal_can_approve() then raise exception 'Deal approval requires manager-level permission.'; end if; if p_decision not in ('approved','rejected') then raise exception 'Decision must be approved or rejected.'; end if; if p_decision='rejected' and length(trim(coalesce(p_comments,'')))<5 then raise exception 'Rejection comments must contain at least 5 characters.'; end if; select * into d from public.deals where id=p_deal_id for update; if not found then raise exception 'Deal not found.'; end if; if d.status<>'pending' then raise exception 'Only pending deals can be decided.'; end if; select * into a from public.approvals where entity_type='deal' and entity_id=p_deal_id and approval_type='commercial' and status='pending' order by requested_at desc limit 1 for update; if a.id is null then raise exception 'Pending commercial approval was not found.'; end if; if p_decision='approved' then r:=public.deal_readiness_v1(p_deal_id); if not coalesce((r->>'ready')::boolean,false) then raise exception 'Deal is no longer ready for approval: %',r->'blockers'; end if; end if; update public.approvals set status=p_decision,approver_id=auth.uid(),comments=nullif(trim(coalesce(p_comments,'')),''),decided_at=now() where id=a.id; update public.deals set status=(case when p_decision='approved' then 'approved'::public.deal_status else 'review'::public.deal_status end),updated_at=now() where id=p_deal_id; insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,metadata,performed_by) values(p_deal_id,case when p_decision='approved' then 'approved' else 'rejected' end,'pending',case when p_decision='approved' then 'approved' else 'review' end,nullif(trim(coalesce(p_comments,'')),''),coalesce(r,'{}'::jsonb),auth.uid()); return jsonb_build_object('deal_id',p_deal_id,'decision',p_decision,'status',case when p_decision='approved' then 'approved' else 'review' end); end $$;
create or replace function public.deal_cancel_v1(p_deal_id uuid,p_reason text) returns public.deals language plpgsql security definer set search_path=public as $$ declare d public.deals; role text:=public.deal_current_role(); begin if role not in ('admin','ceo','manager','dealer') then raise exception 'Deal cancellation is not permitted for this role.'; end if; if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Cancellation reason must contain at least 5 characters.'; end if; select * into d from public.deals where id=p_deal_id for update; if not found then raise exception 'Deal not found.'; end if; if role='dealer' and (d.dealer_id<>auth.uid() or d.status not in ('draft','review')) then raise exception 'Dealer users may cancel only their own draft/review deals.'; end if; if d.status='completed' then raise exception 'Completed deals cannot be cancelled.'; end if; update public.deals set status='cancelled',updated_at=now() where id=p_deal_id returning * into d; update public.approvals set status='cancelled',comments=coalesce(comments,'')||case when comments is null then '' else E'\n' end||'Deal cancelled: '||trim(p_reason),decided_at=coalesce(decided_at,now()) where entity_type='deal' and entity_id=p_deal_id and status='pending'; insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(p_deal_id,'cancelled',null,'cancelled',trim(p_reason),auth.uid()); return d; end $$;
create or replace function public.deal_complete_v1(p_deal_id uuid,p_reason text default null) returns public.deals language plpgsql security definer set search_path=public as $$ declare d public.deals; begin if not public.deal_can_approve() then raise exception 'Deal completion requires manager-level permission.'; end if; select * into d from public.deals where id=p_deal_id for update; if not found then raise exception 'Deal not found.'; end if; if d.status<>'approved' then raise exception 'Only approved deals can be completed.'; end if; if exists(select 1 from public.shipments where deal_id=p_deal_id and status::text not in ('delivered','cancelled')) then raise exception 'All linked shipments must be delivered or cancelled before completing the deal.'; end if; if exists(select 1 from public.invoices where deal_id=p_deal_id and status not in ('paid','cancelled')) then raise exception 'All linked invoices must be paid or cancelled before completing the deal.'; end if; update public.deals set status='completed',updated_at=now() where id=p_deal_id returning * into d; insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(p_deal_id,'completed','approved','completed',nullif(trim(coalesce(p_reason,'')),''),auth.uid()); return d; end $$;
create or replace function public.deal_assign_owner_v1(p_deal_id uuid,p_owner_id uuid,p_reason text default null) returns public.deals language plpgsql security definer set search_path=public as $$ declare d public.deals; role text:=public.deal_current_role(); old_owner uuid; begin if role not in ('admin','ceo','manager','dealer') then raise exception 'Owner assignment is not permitted for this role.'; end if; if role='dealer' and p_owner_id is distinct from auth.uid() then raise exception 'Dealer users may only assign a deal to themselves.'; end if; if not exists(select 1 from public.profiles where id=p_owner_id and active=true) then raise exception 'Selected owner is not an active user.'; end if; select * into d from public.deals where id=p_deal_id for update; if not found then raise exception 'Deal not found.'; end if; if d.status in ('approved','completed') then raise exception 'Approved/completed deal ownership is locked.'; end if; old_owner:=d.dealer_id; update public.deals set dealer_id=p_owner_id,updated_at=now() where id=p_deal_id returning * into d; insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(p_deal_id,'owner_changed',old_owner::text,p_owner_id::text,nullif(trim(coalesce(p_reason,'')),''),auth.uid()); return d; end $$;
revoke all on function public.deal_readiness_v1(uuid) from public,anon; revoke all on function public.deal_submit_review_v1(uuid,text) from public,anon; revoke all on function public.deal_decide_v1(uuid,text,text) from public,anon; revoke all on function public.deal_cancel_v1(uuid,text) from public,anon; revoke all on function public.deal_complete_v1(uuid,text) from public,anon; revoke all on function public.deal_assign_owner_v1(uuid,uuid,text) from public,anon;
grant execute on function public.deal_readiness_v1(uuid) to authenticated,service_role; grant execute on function public.deal_submit_review_v1(uuid,text) to authenticated,service_role; grant execute on function public.deal_decide_v1(uuid,text,text) to authenticated,service_role; grant execute on function public.deal_cancel_v1(uuid,text) to authenticated,service_role; grant execute on function public.deal_complete_v1(uuid,text) to authenticated,service_role; grant execute on function public.deal_assign_owner_v1(uuid,uuid,text) to authenticated,service_role;
